style.css:
cssbody, 
main, 
div[class*="mainContainer"], 
div[class*="page-wrapper"],
div[class*="client-wrapper"] {
    background-image: url("https://ibb.co") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

div[class*="theme-"],
div[id*="copilot-theme-container"] {
    background: transparent !important;
}

p, span, h1, h2, h3, h4, 
div[class*="text"], 
div[class*="message"] {
    color: #ffffff !important;
    text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important;
}

div[class*="userMessage"], 
div[data-author="user"] {
    background-color: rgba(30, 34, 53, 0.85) !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    border-radius: 16px !important;
}

div[class*="agentMessage"], 
div[data-author="agent"],
div[class*="botMessage"] {
    background-color: rgba(15, 15, 25, 0.85) !important;
    border: 1px solid rgba(255, 255, 255, 0.1) !important;
    border-radius: 16px !important;
}

textarea, 
div[class*="textInput"], 
div[class*="inputContainer"] {
    background-color: rgba(20, 20, 30, 0.9) !important;
    color: #ffffff !important;
    border-radius: 12px !important;
}
